impl CapabilityClient for NotificationTemplateClient {
    type Dependencies = PluginDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            activate_version: dependencies.one::<NotificationTemplateActivateVersion>()?,
            create_version: dependencies.one::<NotificationTemplateCreateVersion>()?,
            get_version: dependencies.one::<NotificationTemplateGetVersion>()?,
            list_versions: dependencies.one::<NotificationTemplateListVersions>()?,
            preview: dependencies.one::<NotificationTemplatePreview>()?,
            render: dependencies.one::<NotificationTemplateRender>()?,
        })
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::PluginFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for NotificationTemplateClient {
    fn many_from_dependencies(
        dependencies: &PluginDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    activate_version: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<NotificationTemplateActivateVersion>()?,
                    create_version: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<NotificationTemplateCreateVersion>()?,
                    get_version: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<NotificationTemplateGetVersion>()?,
                    list_versions: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<NotificationTemplateListVersions>()?,
                    preview: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<NotificationTemplatePreview>()?,
                    render: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<NotificationTemplateRender>()?,
                    },
                ))
            })
            .collect()
    }
}

